"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[668],{70668:a=>{a.exports=JSON.parse('{"categories":{"prayer-times":"Namaz vakitleri","location":"Konum","setup":"Namaz ayarlar\u0131n\u0131z","athan":"Ezan","scheduled":"Otomatik ezan","quran":"Kur\'an ve oynatma","hifz":"Haf\u0131zl\u0131k Ko\xe7u","masjid":"Camim","ramadan":"Ramazan","islamic-calendar":"K\u0131ble ve Hicri takvim","fasting":"S\xfcnnet oru\xe7lar","remembrance":"Zikirler, tesbih ve g\xfcnl\xfck hat\u0131rlatmalar","help":"Ba\u015flarken"},"commands":{"Alexa, ask Muslim Companion what is my next prayer":{"does":"S\u0131radaki namaz\u0131, vaktini ve ne kadar kald\u0131\u011f\u0131n\u0131 s\xf6yler; bir camiyi takip ediyorsan\u0131z ikametini de.","say":["Alexa, Muslim Companion\'a sor: s\u0131radaki namaz\u0131m hangisi","Alexa, Muslim Companion\'a sor: s\u0131radaki namaz ne zaman"]},"Alexa, ask Muslim Companion when is Maghrib":{"does":"Bug\xfcn bir namaz\u0131n vaktini s\xf6yler (yats\u0131dan sonra imsak yar\u0131n\u0131nkidir).","say":["Alexa, Muslim Companion\'a sor: ak\u015fam namaz\u0131 ne zaman","Alexa, Muslim Companion\'a sor: sabah namaz\u0131 saat ka\xe7ta"]},"Alexa, ask Muslim Companion for today\'s prayer times":{"does":"Bug\xfcn\xfcn t\xfcm vakitlerini okur. Echo Show\'da bunlar\u0131 s\u0131radaki namaz ve geri say\u0131mla ekranda da g\xf6sterir.","say":["Alexa, Muslim Companion\'a sor: bug\xfcn\xfcn namaz vakitleri","Alexa, Muslim Companion\'a sor: namaz vakitleri"]},"Alexa, ask Muslim Companion to use my Echo\'s location":{"does":"Namaz vakitlerinizi Echo\'nuzun adresinden ayarlar (Alexa uygulamas\u0131nda Cihaz Adresi\'ne izin verdikten sonra). Yaln\u0131zca \u015fehir ve yakla\u015f\u0131k koordinatlar saklan\u0131r.","say":["Alexa, Muslim Companion\'a s\xf6yle: Echo\'mun konumunu kullan","Alexa, Muslim Companion\'a s\xf6yle: konumumu g\xfcncelle"]},"Alexa, ask Muslim Companion for prayer times where I am":{"does":"Telefonunuzdaki Alexa uygulamas\u0131nda: \u015fu an bulundu\u011funuz yerin namaz vakitleri, yaln\u0131zca o yan\u0131t i\xe7in. Evdeki ezanlar\u0131n\u0131z de\u011fi\u015fmez.","say":["Alexa, Muslim Companion\'a sor: bulundu\u011fum yerdeki namaz vakitleri","Alexa, Muslim Companion\'a sor: yak\u0131n\u0131mdaki namaz vakitleri"]},"Yes":{"does":"Muslim Companion\'\u0131n bir sorusunu yan\u0131tlar, \xf6rne\u011fin Echo\'nuzun konumunun kullan\u0131l\u0131p kullan\u0131lmayaca\u011f\u0131n\u0131.","say":["Evet","Hay\u0131r"]},"Alexa, ask Muslim Companion to read my prayer settings":{"does":"Konumunuzu, hesaplama y\xf6nteminizi ve ikindi mezhebinizi, bunlar\u0131 nas\u0131l de\u011fi\u015ftirece\u011finizi s\xf6yler.","say":["Alexa, Muslim Companion\'a s\xf6yle: namaz ayarlar\u0131m\u0131 oku"]},"Alexa, ask Muslim Companion to set my calculation method to Umm al-Qura":{"does":"Namaz vakitlerinizin hesaplanma y\xf6ntemini de\u011fi\u015ftirir: ISNA, D\xfcnya M\xfcsl\xfcman Birli\u011fi, \xdcmm\xfc\'l-Kur\xe2, M\u0131s\u0131r, Kara\xe7i, K\xf6rfez, Kuveyt, Katar, Singapur, Fransa, T\xfcrkiye, Rusya, Tahran veya Caferi. Alexa yeni s\u0131radaki namaz vaktiyle onaylar ve nas\u0131l geri d\xf6nece\u011finizi s\xf6yler.","say":["Alexa, Muslim Companion\'a s\xf6yle: hesaplama y\xf6ntemimi \xdcmm\xfc\'l-Kur\xe2 yap","Alexa, Muslim Companion\'a s\xf6yle: D\xfcnya M\xfcsl\xfcman Birli\u011fi y\xf6ntemini kullan","Alexa, Muslim Companion\'a s\xf6yle: camim ISNA kullan\u0131yor"]},"Alexa, ask Muslim Companion to set my madhab to Hanafi":{"does":"\u0130kindi vaktini ayarlar: Hanefi (daha ge\xe7 ikindi) ya da \u015eafii, Maliki ve Hanbeli i\xe7in standart.","say":["Alexa, Muslim Companion\'a s\xf6yle: mezhebimi Hanefi yap","Alexa, Muslim Companion\'a s\xf6yle: Hanefi mezhebine uyuyorum","Alexa, Muslim Companion\'a s\xf6yle: mezhebimi standart yap"]},"Alexa, ask Muslim Companion which calculation method should I use":{"does":"Ya\u015fad\u0131\u011f\u0131n\u0131z yerde en \xe7ok kullan\u0131lan y\xf6ntemi \xf6nerir (\xf6rne\u011fin Kuzey Amerika\'da ISNA, T\xfcrkiye\'de Diyanet) ve ge\xe7meyi teklif eder: evet ya da hay\u0131r deyin.","say":["Alexa, Muslim Companion\'a sor: hangi hesaplama y\xf6ntemini kullanmal\u0131y\u0131m"]},"Alexa, ask Muslim Companion what calculation method am I using":{"does":"Ayarlar\u0131n\u0131z\u0131 sorman\u0131n ba\u015fka yollar\u0131.","say":["Alexa, Muslim Companion\'a sor: hangi hesaplama y\xf6ntemini kullan\u0131yorum","Alexa, Muslim Companion\'a sor: mezhebim ne"]},"Alexa, ask Muslim Companion to play athan":{"does":"Ezan\u0131 \u015fimdi okur, ard\u0131ndan se\xe7ti\u011finiz dualar ve Kur\'an gelir. Ad\u0131n\u0131 s\xf6yleyebilece\u011finiz sesler aras\u0131nda Mekke, Medine, Mi\u015fari ve Zehrani var.","say":["Alexa, Muslim Companion\'a s\xf6yle: ezan oku","Alexa, Muslim Companion\'a s\xf6yle: Mekke ezan\u0131 oku"]},"Alexa, ask Muslim Companion to play fajr athan":{"does":"O namaz\u0131n ezan\u0131n\u0131 okur (sabah ezan\u0131n\u0131n kendi sesi vard\u0131r).","say":["Alexa, Muslim Companion\'a s\xf6yle: sabah ezan\u0131n\u0131 oku","Alexa, Muslim Companion\'a s\xf6yle: ak\u015fam ezan\u0131n\u0131 oku"]},"Alexa, ask Muslim Companion to test athan":{"does":"Bu Echo\'da sesi kontrol edebilmeniz i\xe7in ezan\u0131 bir kez okur.","say":["Alexa, Muslim Companion\'a s\xf6yle: ezan\u0131 test et"]},"Alexa, ask Muslim Companion what is my scheduled athan status":{"does":"Otomatik ezan\u0131n a\xe7\u0131k olup olmad\u0131\u011f\u0131n\u0131 s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: zamanlanm\u0131\u015f ezan durumum ne"]},"Alexa, ask Muslim Companion to enable scheduled athan":{"does":"Otomatik ezan\u0131 a\xe7ar. Her namaz vaktinde Alexa rutininiz arac\u0131l\u0131\u011f\u0131yla okunur (Kurulum K\u0131lavuzu\'na bak\u0131n).","say":["Alexa, Muslim Companion\'a s\xf6yle: zamanlanm\u0131\u015f ezan\u0131 a\xe7"]},"Alexa, ask Muslim Companion to disable scheduled athan":{"does":"Siz yeniden a\xe7ana kadar t\xfcm namazlar i\xe7in otomatik ezan\u0131 kapat\u0131r.","say":["Alexa, Muslim Companion\'a s\xf6yle: zamanlanm\u0131\u015f ezan\u0131 kapat"]},"Alexa, ask Muslim Companion to play Surah Al-Kahf":{"does":"Herhangi bir sureyi ad\u0131yla ya da numaras\u0131yla, sizin s\xf6yledi\u011finiz gibi (Fatiha, Bakara, Nisa\u2026), kendi k\xe2rinizle ya da ad\u0131n\u0131 verdi\u011finizle (Kari Bedir, Mahir, El-Muayk\u0131li, Sudeys\u2026) ya da her ayetten sonra \u0130ngilizce veya Urduca mealle okur.","say":["Alexa, Muslim Companion\'a s\xf6yle: Kehf suresini oku","Alexa, Muslim Companion\'a s\xf6yle: Bakara suresini Kari Bedir\'den oku","Alexa, Muslim Companion\'a s\xf6yle: Fatiha\'y\u0131 Mahir\'den oku","Alexa, Muslim Companion\'a s\xf6yle: 36 numaral\u0131 sureyi oku","Alexa, Muslim Companion\'a s\xf6yle: Yasin suresini \u0130ngilizce mealiyle oku"]},"Alexa, ask Muslim Companion which reciters do you have":{"does":"K\xe2rileri ya da ad\u0131 bir harfle ba\u015flayanlar\u0131 s\u0131ralar. Alexa s\xf6yledi\u011finiz k\xe2riyi tan\u0131mazsa ayn\u0131 harfle ba\u015flayanlar\u0131 \xf6nerir.","say":["Alexa, Muslim Companion\'a sor: hangi k\xe2riler var","Alexa, Muslim Companion\'a sor: hangi k\xe2riler S ile ba\u015fl\u0131yor"]},"Alexa, ask Muslim Companion to turn on Friday Kahf":{"does":"Her cuma sabah ezan\u0131ndan sonra (ya da panelden ayarlan\u0131rsa \xf6\u011fleden sonra) Kehf suresi okunur.","say":["Alexa, Muslim Companion\'a s\xf6yle: cuma Kehf\'i a\xe7","Alexa, Muslim Companion\'a s\xf6yle: cuma Kehf\'i kapat"]},"Alexa, next":{"does":"Kur\'an \xe7alarken: sonraki ya da \xf6nceki sure. Ezan ve dualar s\u0131ras\u0131nda \u0130leri, \xf6ne atlar.","say":["Alexa, sonraki","Alexa, \xf6nceki"]},"Alexa, start over":{"does":"Ge\xe7erli sureyi ba\u015ftan ba\u015flat\u0131r.","say":["Alexa, ba\u015ftan ba\u015fla"]},"Alexa, pause":{"does":"K\u0131raati duraklat\u0131r ve ayn\u0131 yerden devam eder.","say":["Alexa, duraklat","Alexa, devam et"]},"Alexa, stop":{"does":"Ezan\u0131 ya da k\u0131raati istedi\u011finiz an durdurur.","say":["Alexa, dur","Alexa, iptal"]},"Alexa, ask Muslim Companion how far am I in the Quran":{"does":"Kur\'an Yolculu\u011funuzu s\xf6yler: dinleme s\xfcresi ve hatmin ne kadar\u0131n\u0131 dinledi\u011finiz.","say":["Alexa, Muslim Companion\'a sor: Kur\'an\'da ne kadar ilerledim"]},"Alexa, shuffle":{"does":"Kur\'an Program\u0131 sayfas\u0131nda rastgele ya da kesintisiz Kur\'an\'\u0131 nas\u0131l se\xe7ece\u011finizi a\xe7\u0131klar.","say":["Alexa, kar\u0131\u015ft\u0131r","Alexa, tekrarla"]},"Alexa, ask Muslim Companion to start Hifz":{"does":"Ge\xe7erli dersinizi okur: her ayet tekrarlan\u0131r, sonra dersin tamam\u0131 birlikte. Echo Show\'da ayet ekranda g\xf6r\xfcn\xfcr.","say":["Alexa, Muslim Companion\'a s\xf6yle: haf\u0131zl\u0131\u011f\u0131 ba\u015flat"]},"Alexa, tell Muslim Companion I memorized it":{"does":"Dersi ezberlendi olarak i\u015faretler ve sonrakine ge\xe7er.","say":["Alexa, Muslim Companion\'a s\xf6yle: ezberledim"]},"Alexa, ask Muslim Companion to repeat each ayah five times":{"does":"Her ayetin ka\xe7 kez tekrarlanaca\u011f\u0131n\u0131 ayarlar: 1, 3, 5, 7 veya 10.","say":["Alexa, Muslim Companion\'a s\xf6yle: her ayeti be\u015f kez tekrarla"]},"Alexa, ask Muslim Companion how is my Hifz":{"does":"Ka\xe7 ayet ezberledi\u011finizi ve ge\xe7erli dersinizi s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: haf\u0131zl\u0131\u011f\u0131m nas\u0131l gidiyor"]},"Alexa, ask Muslim Companion when is iqamah":{"does":"Takip etti\u011finiz camideki s\u0131radaki ikamet vaktini s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: ikamet ne zaman"]},"Alexa, ask Muslim Companion when is jumuah":{"does":"Caminizde bu haftaki cuma namaz\u0131 vaktini ya da vakitlerini s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: cuma namaz\u0131 ne zaman"]},"Alexa, ask Muslim Companion to turn on Ramadan mode":{"does":"Ramazan modunu a\xe7ar ya da kapat\u0131r: sahur hat\u0131rlatmas\u0131, ak\u015famda iftar ve yats\u0131dan sonra teravih k\u0131raati.","say":["Alexa, Muslim Companion\'a s\xf6yle: Ramazan modunu a\xe7","Alexa, Muslim Companion\'a s\xf6yle: Ramazan modunu kapat"]},"Alexa, ask Muslim Companion is Ramadan mode on":{"does":"Ramazan modunun a\xe7\u0131k olup olmad\u0131\u011f\u0131n\u0131 s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: Ramazan modu a\xe7\u0131k m\u0131"]},"Alexa, ask Muslim Companion when is suhoor":{"does":"Sahurun ne zaman bitti\u011fini (imsak) ve iftar\u0131n ne zaman oldu\u011funu (ak\u015fam) s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: sahur ne zaman","Alexa, Muslim Companion\'a sor: iftar ne zaman"]},"Alexa, ask Muslim Companion which way is the Qibla":{"does":"Kay\u0131tl\u0131 konumunuzdan k\u0131ble y\xf6n\xfcn\xfc ger\xe7ek kuzeyden derece ve pusula y\xf6n\xfc olarak, Mekke\'nin ne kadar uzak oldu\u011funu s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: k\u0131ble ne tarafta","Alexa, Muslim Companion\'a sor: k\u0131ble nerede"]},"Alexa, ask Muslim Companion what is the Hijri date":{"does":"Bug\xfcn\xfcn Hicri tarihini (uygulama ve Echo Show ile ayn\u0131 tarih) ve bug\xfcn \xf6zel bir g\xfcn ise bunu s\xf6yler.","say":["Alexa, Muslim Companion\'a sor: Hicri tarih ne","Alexa, Muslim Companion\'a sor: bug\xfcn \u0130slami tarih ne"]},"Alexa, ask Muslim Companion when is Ramadan":{"does":"Ramazan, bayram, A\u015fure, Arefe, Hicri y\u0131lba\u015f\u0131, son on gece ya da eyyam-\u0131 b\xeez ne zaman, geri say\u0131mla. Tarihler \xdcmm\xfc\'l-Kur\xe2\'ya g\xf6redir ve hilalin yerel olarak g\xf6zlendi\u011fi yerlerde bir g\xfcn farkl\u0131 olabilir.","say":["Alexa, Muslim Companion\'a sor: Ramazan ne zaman","Alexa, Muslim Companion\'a sor: bayrama ka\xe7 g\xfcn var","Alexa, Muslim Companion\'a sor: eyyam-\u0131 b\xeez ne zaman"]},"Alexa, ask Muslim Companion when is the next Sunnah fast":{"does":"S\u0131radaki s\xfcnnet oru\xe7: pazartesi ve per\u015fembe, eyyam-\u0131 b\xeez, Arefe, A\u015fure ve \u015eevval\'in alt\u0131 g\xfcn\xfc.","say":["Alexa, Muslim Companion\'a sor: s\u0131radaki s\xfcnnet oru\xe7 ne zaman","Alexa, Muslim Companion\'a sor: yar\u0131n oru\xe7 tutmal\u0131 m\u0131y\u0131m"]},"Alexa, ask Muslim Companion to turn on fasting reminders":{"does":"S\xfcnnet oru\xe7tan \xf6nceki ak\u015fam yats\u0131dan sonra, Muslim Companion rutininiz arac\u0131l\u0131\u011f\u0131yla bir hat\u0131rlatma.","say":["Alexa, Muslim Companion\'a s\xf6yle: oru\xe7 hat\u0131rlatmalar\u0131n\u0131 a\xe7","Alexa, Muslim Companion\'a s\xf6yle: oru\xe7 hat\u0131rlatmalar\u0131n\u0131 kapat"]},"Alexa, ask Muslim Companion to play the morning adhkar":{"does":"\xc2yet\xfc\'l-K\xfcrs\xee, ard\u0131ndan \u0130hlas, Felak ve Nas \xfc\xe7er kez, k\u0131raatle.","say":["Alexa, Muslim Companion\'a s\xf6yle: sabah zikirlerini oku","Alexa, Muslim Companion\'a s\xf6yle: ak\u015fam zikirlerini oku"]},"Alexa, ask Muslim Companion to turn on morning and evening adhkar":{"does":"Her g\xfcn sabah zikirlerini sabah namaz\u0131ndan sonra, ak\u015fam zikirlerini ikindiden sonra okur (ya da panelden ayarlan\u0131rsa ak\u015famdan sonra).","say":["Alexa, Muslim Companion\'a s\xf6yle: sabah ve ak\u015fam zikirlerini a\xe7","Alexa, Muslim Companion\'a s\xf6yle: ak\u015fam zikirlerini kapat"]},"Alexa, ask Muslim Companion to start tasbih":{"does":"Zikri sizinle sakin bir tempoda sayar. Bir zikir s\xf6ylemezseniz namaz sonras\u0131 tesbihat\u0131 y\xf6netir: 33 S\xfcbhanallah, 33 Elhamd\xfclillah ve 34 Allahu Ekber. Echo Show\'da saymak i\xe7in ekrana dokunun.","say":["Alexa, Muslim Companion\'a s\xf6yle: tesbihe ba\u015fla","Alexa, Muslim Companion\'a s\xf6yle: 33 S\xfcbhanallah say"]},"Alexa, ask Muslim Companion for today\'s dua":{"does":"Kayna\u011f\u0131yla birlikte k\u0131sa bir g\xfcnl\xfck dua, hadis ya da Allah\'\u0131n bir ismi; yay\u0131mlanmadan \xf6nce bir \xe2lim taraf\u0131ndan incelenir.","say":["Alexa, Muslim Companion\'a sor: bug\xfcn\xfcn duas\u0131","Alexa, Muslim Companion\'a sor: bug\xfcn\xfcn hadisi","Alexa, Muslim Companion\'a sor: g\xfcn\xfcn esmas\u0131n\u0131"],"soonNote":"Yak\u0131nda: her dua, hadis ve isim \xf6nce bir \xe2lim taraf\u0131ndan kontrol ediliyor"},"Alexa, open Muslim Companion":{"does":"Beceriyi ba\u015flat\u0131r (ge\xe7erli namaz\u0131n ezan\u0131n\u0131 okur).","say":["Alexa, Muslim Companion\'\u0131 a\xe7"]},"Alexa, ask Muslim Companion for help":{"does":"Neler sorabilece\u011finizi s\u0131ralar.","say":["Alexa, Muslim Companion\'a sor: yard\u0131m"]},"Alexa, ask Muslim Companion to link my phone":{"does":"Bu Echo\'yu uygulamadaki alt\u0131 haneli kodla (Daha fazla, sonra Alexa) telefondaki Salat-e-Mustaqeem hesab\u0131n\u0131za ba\u011flar; b\xf6ylece H\u0131fz ilerlemeniz telefonda g\xf6r\xfcn\xfcr.","say":["Alexa, Muslim Companion\'dan telefonumu ba\u011flamas\u0131n\u0131 iste","Alexa, Muslim Companion\'dan telefonumu 123456 koduyla ba\u011flamas\u0131n\u0131 iste"]}}}')}}]);